WITH filtered_order_items AS (SELECT * FROM order_items WHERE quantity <= 3 OR product_id IN (13, 21, 30, 36)), summary AS (SELECT order_id, CASE WHEN unit_price >= 390 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(quantity) AS total_quantity, SUM(unit_price) AS total_unit_price FROM filtered_order_items GROUP BY order_id, CASE WHEN unit_price >= 390 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END) SELECT * FROM summary WHERE total_unit_price > 1400 ORDER BY order_id, unit_price_bucket LIMIT 3;
